'use client'

import type { BookPreviewContentsEntry } from './types'

export type PdfTextItem = { str?: string }
export type PdfTextContent = { items: PdfTextItem[] }

export type PdfPageProxy = {
  getViewport: (options: { scale: number; rotation?: number }) => {
    width: number
    height: number
    /** Maps a PDF user-space rect to CSS pixels for this viewport. */
    convertToViewportRectangle?: (rect: number[]) => number[]
  }
  getTextContent?: () => Promise<PdfTextContent>
  getAnnotations?: (options?: { intent?: string }) => Promise<PdfAnnotation[]>
  render: (options: {
    canvasContext: CanvasRenderingContext2D
    viewport: { width: number; height: number }
    transform?: number[]
  }) => { promise: Promise<void>; cancel: () => void }
}

export type PdfAnnotation = {
  subtype?: string
  /** [x1, y1, x2, y2] in PDF user space — null on malformed annotations. */
  rect?: number[] | null
  url?: string
  unsafeUrl?: string
  dest?: PdfOutlineNode['dest']
}

export type PdfDestinationRef = { num: number; gen: number }

export type PdfOutlineNode = {
  title?: string
  dest?: string | unknown[] | null
  items?: PdfOutlineNode[] | null
}

export type PdfDocumentProxy = {
  numPages: number
  getPage: (pageNumber: number) => Promise<PdfPageProxy>
  getOutline?: () => Promise<PdfOutlineNode[] | null>
  getDestination?: (id: string) => Promise<unknown[] | null>
  getPageIndex?: (ref: PdfDestinationRef) => Promise<number>
}

export type PdfLoadResult = {
  task: PdfLoadingTask
  doc: PdfDocumentProxy
}

export type PdfSource = string | { data: ArrayBuffer }

/** The pdf.js loading task, typed loosely — engines need it to destroy a
    document that is still waiting on a password prompt. */
export type PdfLoadingTask = {
  promise: Promise<unknown>
  destroy: () => Promise<void>
  onPassword?: (
    updatePassword: (password: string) => void,
    reason: number,
  ) => void
}

/** pdf.js asks for a password through this bridge: `submit` answers the
    prompt, and an `incorrect` re-ask means the last answer was rejected. */
export type PdfPasswordRequest = {
  incorrect: boolean
  submit: (password: string) => void
}

export async function loadPdfDocument(
  src: PdfSource,
  options?: {
    onPassword?: (request: PdfPasswordRequest) => void
    /** Fires synchronously with the task so callers can destroy a document
        that never resolves (e.g. abandoned password prompt). */
    onTask?: (task: PdfLoadingTask) => void
    /** Give up after this many ms — a stalled fetch/worker otherwise leaves
        task.promise pending forever and the reader spins indefinitely. */
    timeoutMs?: number
  },
): Promise<PdfLoadResult> {
  const pdfjs = await import('pdfjs-dist')
  if (
    !pdfjs.GlobalWorkerOptions.workerSrc &&
    !pdfjs.GlobalWorkerOptions.workerPort
  ) {
    pdfjs.GlobalWorkerOptions.workerSrc = new URL(
      'pdfjs-dist/build/pdf.worker.min.mjs',
      import.meta.url,
    ).toString()
  }
  const source = typeof src === 'string' ? { url: src } : src
  const task = pdfjs.getDocument(source) as unknown as PdfLoadingTask
  options?.onTask?.(task)
  // A parked password prompt is a user wait, not a stalled load — the
  // timeout must not fire while one is outstanding.
  let passwordPending = false
  if (options?.onPassword) {
    const responses = (
      pdfjs as { PasswordResponses?: { INCORRECT_PASSWORD?: number } }
    ).PasswordResponses
    const onPassword = options.onPassword
    task.onPassword = (updatePassword, reason) => {
      passwordPending = true
      onPassword({
        incorrect: reason === (responses?.INCORRECT_PASSWORD ?? 2),
        submit: (password: string) => {
          passwordPending = false
          updatePassword(password)
        },
      })
    }
  }
  const timeoutMs = options?.timeoutMs
  let timer: ReturnType<typeof setTimeout> | undefined
  try {
    const doc = timeoutMs
      ? await Promise.race([
          task.promise as Promise<PdfDocumentProxy>,
          new Promise<never>((_, reject) => {
            const arm = () => {
              timer = setTimeout(() => {
                if (passwordPending) {
                  arm()
                  return
                }
                reject(new Error(`PDF load timed out after ${timeoutMs}ms`))
              }, timeoutMs)
            }
            arm()
          }),
        ])
      : ((await task.promise) as PdfDocumentProxy)
    return { task, doc }
  } catch (error) {
    // A timed-out task is dead weight — destroy it so the worker is freed
    // instead of leaving a zombie load running in the background.
    await task.destroy().catch(() => {})
    throw error
  } finally {
    if (timer) clearTimeout(timer)
  }
}

// Uncapped devicePixelRatio turns a page into a ~30MP canvas on 3x phones;
// past 2x the extra pixels are invisible while reading.
const PDF_MAX_RENDER_DPR = 2

function defaultPixelRatio(): number {
  if (typeof window === 'undefined') return 1
  return Math.min(PDF_MAX_RENDER_DPR, Math.max(1, window.devicePixelRatio || 1))
}

export function renderPdfPageToCanvas(input: {
  page: PdfPageProxy
  canvas: HTMLCanvasElement
  scale: number
  /** Extra rotation in degrees (0/90/180/270) on top of the page's own. */
  rotation?: number
  pixelRatio?: number
}): { promise: Promise<void>; cancel: () => void } {
  const pixelRatio = input.pixelRatio ?? defaultPixelRatio()
  const viewport = input.page.getViewport({
    scale: input.scale,
    rotation: input.rotation,
  })
  const context = input.canvas.getContext('2d')
  if (!context) {
    throw new Error('Could not create a canvas for this PDF page.')
  }
  input.canvas.width = Math.max(1, Math.floor(viewport.width * pixelRatio))
  input.canvas.height = Math.max(1, Math.floor(viewport.height * pixelRatio))
  input.canvas.style.width = `${Math.floor(viewport.width)}px`
  input.canvas.style.height = `${Math.floor(viewport.height)}px`
  const transform =
    pixelRatio === 1 ? undefined : [pixelRatio, 0, 0, pixelRatio, 0, 0]
  return input.page.render({ canvasContext: context, viewport, transform })
}

/**
 * Plain text of a page, for search and speech.
 *
 * This is deliberately separate from the selectable text layer below. A curl
 * sheet is mid-flight 3D-transformed and cloned outside React, so putting
 * real selectable spans on it would break selection and cost a layer per
 * page. Paged curl reading wants *findable* text; only the flat reader wants
 * *selectable* text.
 */
export async function extractPdfPageText(page: PdfPageProxy): Promise<string> {
  if (typeof page.getTextContent !== 'function') return ''
  try {
    const content = await page.getTextContent()
    return content.items
      .map((item) => item.str ?? '')
      .join(' ')
      .replace(/\s+/g, ' ')
      .trim()
  } catch {
    // An image-only or malformed page simply has no text.
    return ''
  }
}

/**
 * Renders a real, selectable text layer over an already-painted canvas.
 * The container must be positioned and exactly overlay the canvas box.
 */
export async function renderPdfTextLayer(input: {
  page: PdfPageProxy
  container: HTMLElement
  scale: number
  rotation?: number
}): Promise<{ cancel: () => void }> {
  if (typeof input.page.getTextContent !== 'function') {
    return { cancel: () => {} }
  }
  const pdfjs = await import('pdfjs-dist')
  const viewport = input.page.getViewport({
    scale: input.scale,
    rotation: input.rotation,
  })
  const textContentSource = await input.page.getTextContent()
  const layer = new pdfjs.TextLayer({
    textContentSource: textContentSource as never,
    container: input.container,
    viewport: viewport as never,
  })
  await layer.render()
  return { cancel: () => layer.cancel() }
}

/** Intrinsic aspect ratio (height / width) of a page at scale 1. */
export function pdfPageAspectRatio(page: PdfPageProxy): number {
  const base = page.getViewport({ scale: 1 })
  if (!(base.width > 0) || !(base.height > 0)) return Math.SQRT2
  return base.height / base.width
}

function canvasToObjectUrl(canvas: HTMLCanvasElement): Promise<string> {
  return new Promise((resolve) => {
    // Blob URLs keep the bitmap out of the JS heap. A base64 data URL of the
    // same page is ~33% larger and is copied again by every DOM clone the
    // flip book makes, so it is only the fallback.
    if (typeof canvas.toBlob !== 'function') {
      resolve(canvas.toDataURL('image/png'))
      return
    }
    canvas.toBlob((blob) => {
      resolve(blob ? URL.createObjectURL(blob) : canvas.toDataURL('image/png'))
    }, 'image/png')
  })
}

/** Release a URL produced by `rasterizePdfPage`. Safe for data-URL fallbacks. */
export function releaseRasterUrl(src: string | undefined | null): void {
  if (!src || !src.startsWith('blob:')) return
  try {
    URL.revokeObjectURL(src)
  } catch {
    // Already revoked, or the document is being torn down.
  }
}

// A document outline can nest arbitrarily deep; the contents menu only needs
// a few levels of indentation, and a malformed file should never grow the
// menu without bound.
const OUTLINE_MAX_ENTRIES = 300
const OUTLINE_MAX_DEPTH = 4

function outlineDestinationRef(
  dest: PdfOutlineNode['dest'],
): PdfDestinationRef | string | number | null {
  if (typeof dest === 'string') return dest
  if (Array.isArray(dest)) {
    const first = dest[0] as
      | Partial<PdfDestinationRef>
      | number
      | null
      | undefined
    // Some writers emit a bare zero-based page index instead of a reference.
    if (typeof first === 'number') return first
    if (first && typeof first.num === 'number')
      return first as PdfDestinationRef
  }
  return null
}

/**
 * Reads the document outline ("bookmarks") into flat contents entries for the
 * toolbar menu. Entries without a resolvable page destination are dropped —
 * external links and action bookmarks have nowhere in the reader to go.
 */
export async function resolvePdfOutline(
  doc: PdfDocumentProxy,
): Promise<BookPreviewContentsEntry[]> {
  if (
    typeof doc.getOutline !== 'function' ||
    typeof doc.getPageIndex !== 'function'
  ) {
    return []
  }
  let outline: PdfOutlineNode[] | null
  try {
    outline = await doc.getOutline()
  } catch {
    return []
  }
  if (!outline || outline.length === 0) return []

  const flat: {
    title: string
    depth: number
    ref: PdfDestinationRef | string | number | null
  }[] = []
  const walk = (nodes: PdfOutlineNode[], depth: number) => {
    for (const node of nodes) {
      if (flat.length >= OUTLINE_MAX_ENTRIES) return
      const title = node.title?.trim()
      if (title) {
        flat.push({
          title,
          depth: Math.min(depth, OUTLINE_MAX_DEPTH),
          ref: outlineDestinationRef(node.dest),
        })
      }
      if (node.items && node.items.length > 0) walk(node.items, depth + 1)
    }
  }
  walk(outline, 0)

  const entries = await Promise.all(
    flat.map(async (item) => {
      if (!item.ref) return null
      const pageIndex = await resolvePdfDestPageIndex(doc, item.ref)
      return pageIndex === null
        ? null
        : { title: item.title, pageIndex, depth: item.depth }
    }),
  )
  return entries.filter(
    (entry): entry is BookPreviewContentsEntry => entry !== null,
  )
}

/**
 * Resolves an explicit or named PDF destination to a zero-based page index.
 * Explicit arrays carry a page reference ({num, gen}) or, in some files, a
 * bare page index; named destinations go through getDestination first.
 * Anything that cannot be resolved inside this document returns null.
 */
async function resolvePdfDestPageIndex(
  doc: PdfDocumentProxy,
  dest: PdfDestinationRef | string | number | null | undefined,
): Promise<number | null> {
  if (
    dest === null ||
    dest === undefined ||
    typeof doc.getPageIndex !== 'function'
  ) {
    return null
  }
  // A bare number is already a zero-based page index.
  if (typeof dest === 'number') {
    return dest >= 0 && dest < doc.numPages ? dest : null
  }
  try {
    let ref: PdfDestinationRef | string = dest
    if (typeof ref === 'string') {
      const resolved = ((await doc.getDestination?.(ref)) ??
        null) as PdfOutlineNode['dest']
      const inner = outlineDestinationRef(resolved)
      if (typeof inner === 'number') {
        return inner >= 0 && inner < doc.numPages ? inner : null
      }
      if (!inner || typeof inner === 'string') return null
      ref = inner
    }
    const pageIndex = await doc.getPageIndex(ref)
    if (
      !Number.isFinite(pageIndex) ||
      pageIndex < 0 ||
      pageIndex >= doc.numPages
    )
      return null
    return pageIndex
  } catch {
    return null
  }
}

// Link annotations may carry unsanitized URLs (unsafeUrl). Only schemes that
// are safe to navigate to pass through — javascript: and friends are dropped.
const LINK_PROTOCOLS = new Set(['http:', 'https:', 'mailto:', 'tel:'])

export function sanitizePdfLinkUrl(
  raw: string | undefined | null,
): string | null {
  if (!raw) return null
  try {
    const url = new URL(raw)
    return LINK_PROTOCOLS.has(url.protocol) ? url.href : null
  } catch {
    return null
  }
}

export type PdfPageLink = {
  /** CSS-pixel rect within the rendered page box at the given scale. */
  left: number
  top: number
  width: number
  height: number
  target: { kind: 'page'; pageIndex: number } | { kind: 'url'; url: string }
}

/**
 * Resolves a page's link annotations into positioned click targets. Internal
 * document links become page indexes for the reader to navigate; external
 * links become sanitized URLs. Anything else (named actions, attachments,
 * malformed rects) is dropped — a dead annotation is better than a wrong one.
 */
export async function resolvePdfPageLinks(input: {
  page: PdfPageProxy
  doc: PdfDocumentProxy
  scale: number
  rotation?: number
}): Promise<PdfPageLink[]> {
  if (typeof input.page.getAnnotations !== 'function') return []
  let annotations: PdfAnnotation[]
  try {
    annotations = await input.page.getAnnotations({ intent: 'display' })
  } catch {
    return []
  }
  const viewport = input.page.getViewport({
    scale: input.scale,
    rotation: input.rotation,
  })
  const convert = viewport.convertToViewportRectangle
  if (!convert) return []

  const links: PdfPageLink[] = []
  for (const annotation of annotations) {
    if (annotation.subtype !== 'Link') continue
    const rect = annotation.rect
    if (!rect || rect.length < 4) continue
    const mapped = convert.call(viewport, rect)
    if (!mapped || mapped.length < 4) continue
    const left = Math.min(mapped[0], mapped[2])
    const top = Math.min(mapped[1], mapped[3])
    const width = Math.abs(mapped[2] - mapped[0])
    const height = Math.abs(mapped[3] - mapped[1])
    if (width < 1 || height < 1) continue

    const url = sanitizePdfLinkUrl(annotation.url ?? annotation.unsafeUrl)
    if (url) {
      links.push({ left, top, width, height, target: { kind: 'url', url } })
      continue
    }
    const dest = annotation.dest
    // Array destinations carry the target in their first slot (a page ref or
    // a bare page index); strings are named destinations.
    const target = Array.isArray(dest)
      ? (dest[0] as PdfDestinationRef | number | undefined)
      : dest
    const pageIndex = await resolvePdfDestPageIndex(input.doc, target)
    if (pageIndex !== null) {
      links.push({
        left,
        top,
        width,
        height,
        target: { kind: 'page', pageIndex },
      })
    }
  }
  return links
}

export async function rasterizePdfPage(input: {
  page: PdfPageProxy
  cssWidth: number
  cssHeight: number
  pixelRatio?: number
  rotation?: number
}): Promise<{ src: string; width: number; height: number }> {
  const pixelRatio = input.pixelRatio ?? defaultPixelRatio()
  const base = input.page.getViewport({ scale: 1, rotation: input.rotation })
  const fit = Math.min(
    input.cssWidth / base.width,
    input.cssHeight / base.height,
  )
  const viewport = input.page.getViewport({
    scale: fit,
    rotation: input.rotation,
  })
  const canvas = document.createElement('canvas')
  await renderPdfPageToCanvas({
    page: input.page,
    canvas,
    scale: fit,
    rotation: input.rotation,
    pixelRatio,
  }).promise
  const src = await canvasToObjectUrl(canvas)
  // Drop the backing store now that the bitmap is encoded; Safari keeps large
  // canvases alive well past the last reference otherwise.
  canvas.width = 0
  canvas.height = 0
  return {
    src,
    width: Math.floor(viewport.width),
    height: Math.floor(viewport.height),
  }
}

'use client'

import { useEffect, useRef, useState } from 'react'
import {
  extractPdfPageText,
  loadPdfDocument,
  pdfPageAspectRatio,
  rasterizePdfPage,
  releaseRasterUrl,
  type PdfDocumentProxy,
  type PdfLoadingTask,
} from '../pdf-runtime'
import type { BookPreviewError } from '../types'

export type PdfSheet = {
  id: string
  src: string
  width: number
  height: number
  /** Plain page text, when extraction is enabled. Empty for image-only pages. */
  text: string
  /** True once extraction ran for this page — distinguishes "no text" from
      "not read yet", which windowed search needs. A page whose extraction
      permanently fails is also marked, so the search-index signal settles. */
  textExtracted: boolean
  /** The page's raster failed after all retries — stays blank, and stops
      counting as pending so the preparing state can clear. */
  failed?: boolean
}

type UsePdfSheetsOptions = {
  pdfUrl: string | undefined
  /** False for page-backed sources; the hook then does no work at all. */
  enabled: boolean
  /** Rasterization is reordered so the page being read paints first. */
  pageIndex: number
  rasterWidth: number
  /**
   * "uniform" sizes every sheet to page 1's aspect ratio, which is what a
   * bound book needs -- leaves cannot each be a different shape. "per-page"
   * measures each page, for continuous scrolling.
   */
  sizing: 'uniform' | 'per-page'
  /** Pull plain text per page so the reader can search and speak a PDF. */
  extractText?: boolean
  /**
   * Bound live rasters to +/- this many pages around the reading position.
   * Pages that fall outside are revoked and re-render on return, so a long
   * document holds ~2*windowRadius+1 decoded bitmaps instead of all of them.
   * Omit for engines that must keep every sheet painted (the curl flip book
   * owns all leaves at once).
   */
  windowRadius?: number
  /**
   * Fail with `maxPagesMessage` when the document exceeds this page count.
   * For engines that hold every raster at once, a page-flip of a 400-page
   * file is a hang, not a feature — they should point the reader at a
   * bounded mode instead of starting work.
   */
  maxPages?: number
  maxPagesMessage?: string
  onError: (error: BookPreviewError) => void
  errorMessage: string
}

type UsePdfSheetsResult = {
  sheets: PdfSheet[] | null
  /** The open document, once loaded — engines use it for outlines etc. */
  doc: PdfDocumentProxy | null
  /** height / width of page 1, once known. Null until the document opens. */
  ratio: number | null
  prepared: number
  preparing: boolean
  /** True while the background text index still has pages to read — search
      results grow as it catches up. */
  textPending: boolean
  /** Set while the document waits on a password. `incorrect` means the last
      answer was rejected. */
  passwordRequest: { incorrect: boolean } | null
  submitPassword: (password: string) => void
  /** Abandon the prompt — the document load is destroyed and reported. */
  cancelPassword: () => void
}

/**
 * Opens a PDF and rasterizes its pages into image sheets.
 *
 * Every sheet is mounted up front with an empty src so the reader knows the
 * page count immediately and stays usable while pages fill in behind it.
 * Rasters are object URLs, released together when the document is torn down --
 * they cannot be released per sheet, because the curl engine clones the <img>
 * nodes into a flip book that React does not own.
 */
export function usePdfSheets({
  pdfUrl,
  enabled,
  pageIndex,
  rasterWidth,
  sizing,
  extractText = false,
  windowRadius,
  maxPages,
  maxPagesMessage,
  onError,
  errorMessage,
}: UsePdfSheetsOptions): UsePdfSheetsResult {
  // Sheets are keyed to the url that produced them: when pdfUrl changes the
  // stale document stops matching the gate below, so no effect-body reset is
  // needed and a superseded load can never publish its pages.
  const [doc, setDoc] = useState<{
    url: string
    proxy: PdfDocumentProxy
    ratio: number | null
    sheets: PdfSheet[] | null
  } | null>(null)
  const [passwordRequest, setPasswordRequest] = useState<{
    incorrect: boolean
  } | null>(null)
  const priorityRef = useRef(pageIndex + 1)
  const wakeRef = useRef<(() => void) | null>(null)
  const reportError = useRef(onError)
  const message = useRef(errorMessage)
  // The loading task is tracked from the moment it exists — a document that
  // is parked on a password prompt must still be destroyable on teardown.
  const taskRef = useRef<PdfLoadingTask | null>(null)
  const passwordSubmitRef = useRef<((password: string) => void) | null>(null)
  const passwordCancelledRef = useRef(false)

  const submitPassword = (password: string) => {
    passwordSubmitRef.current?.(password)
  }

  const cancelPassword = () => {
    passwordCancelledRef.current = true
    passwordSubmitRef.current = null
    setPasswordRequest(null)
    // Destroying the pending task rejects its promise; the open() catch turns
    // it into a "password required" error the reader can retry from.
    void taskRef.current?.destroy().catch(() => {})
  }

  useEffect(() => {
    priorityRef.current = pageIndex + 1
    reportError.current = onError
    message.current = errorMessage
    // Resume a parked windowed drain — the new reading position may need
    // pages the loop skipped.
    wakeRef.current?.()
  })

  useEffect(() => {
    if (!enabled || !pdfUrl) return
    let cancelled = false
    let loaded: Awaited<ReturnType<typeof loadPdfDocument>> | null = null
    let uniformHeight = 0
    let pixelRatio = 1
    // Live rasters by page number; doubles as the teardown revocation list.
    const rendered = new Map<number, string>()
    // Pages already tried — attempted failures stay blank rather than
    // re-failing on every pass, matching the old once-only queue.
    const attempted = new Set<number>()
    // Per-page failure count — a transient hiccup (render cancelled under
    // worker churn, canvas/context pressure) gets a retry budget before the
    // page is declared dead. Without this a single transient failure pinned
    // the "preparing" state forever until refresh.
    const failures = new Map<number, number>()
    const MAX_PAGE_FAILURES = 3
    // Text-index retries share the failures map keyed above the page range.
    const TEXT_KEY_OFFSET = 1_000_000
    // Pages whose text has been read — the background index drain fills this
    // behind the raster window so search covers the whole document.
    const textDone = new Set<number>()

    const inWindow = (pageNumber: number, priority: number): boolean =>
      windowRadius === undefined ||
      Math.abs(pageNumber - priority) <= windowRadius

    // Pages commit through this guarded writer. It stays a flat async
    // function — not a loop body — so each post-await state write is provably
    // dominated by a cancellation check.
    async function renderSheet(url: string, pageNumber: number): Promise<void> {
      if (cancelled || !loaded) return
      attempted.add(pageNumber)
      try {
        const page = await loaded.doc.getPage(pageNumber)
        // Text first: it is cheap, and it makes the page findable before
        // its bitmap has finished painting.
        const text = extractText ? await extractPdfPageText(page) : ''
        if (extractText) textDone.add(pageNumber)
        if (cancelled) return
        const cssHeight =
          sizing === 'uniform'
            ? uniformHeight
            : Math.round(rasterWidth * pdfPageAspectRatio(page))
        const raster = await rasterizePdfPage({
          page,
          cssWidth: rasterWidth,
          cssHeight,
          pixelRatio,
        })
        if (cancelled) {
          releaseRasterUrl(raster.src)
          return
        }
        const previous = rendered.get(pageNumber)
        if (previous) releaseRasterUrl(previous)
        rendered.set(pageNumber, raster.src)
        const id = `pdf-${pageNumber}`
        setDoc((current) =>
          current && current.url === url && current.sheets
            ? {
                ...current,
                sheets: current.sheets.map((sheet) =>
                  sheet.id === id
                    ? {
                        ...sheet,
                        src: raster.src,
                        width: raster.width,
                        height: raster.height,
                        text,
                        textExtracted: true,
                      }
                    : sheet,
                ),
              }
            : current,
        )
      } catch {
        if (cancelled) return
        const count = (failures.get(pageNumber) ?? 0) + 1
        failures.set(pageNumber, count)
        if (count < MAX_PAGE_FAILURES) {
          // Transient — let the drain re-pick it after a beat.
          attempted.delete(pageNumber)
          await new Promise((resolve) => setTimeout(resolve, 300))
          return
        }
        // Dead for good — a single bad page stays blank instead of failing
        // the document, and stops counting toward "preparing".
        const id = `pdf-${pageNumber}`
        setDoc((current) =>
          current && current.url === url && current.sheets
            ? {
                ...current,
                sheets: current.sheets.map((sheet) =>
                  sheet.id === id ? { ...sheet, failed: true } : sheet,
                ),
              }
            : current,
        )
      }
    }

    // Revokes rasters that fell behind the reading position. The extracted
    // text stays — it is small — so a pruned page re-renders its bitmap only.
    function prune(url: string, priority: number): void {
      if (windowRadius === undefined) return
      for (const [pageNumber, src] of rendered) {
        if (inWindow(pageNumber, priority)) continue
        rendered.delete(pageNumber)
        attempted.delete(pageNumber)
        failures.delete(pageNumber)
        releaseRasterUrl(src)
        const id = `pdf-${pageNumber}`
        setDoc((current) =>
          current && current.url === url && current.sheets
            ? {
                ...current,
                sheets: current.sheets.map((sheet) =>
                  sheet.id === id
                    ? { ...sheet, src: '', failed: false }
                    : sheet,
                ),
              }
            : current,
        )
      }
    }

    // Nearest unrendered page to the reading position, expanding outward —
    // a reader at page 50 gets 50, 51, 49, 52, 48… instead of waiting for
    // everything before it.
    function pickNext(priority: number, count: number): number | undefined {
      if (!attempted.has(priority) && priority <= count) return priority
      for (let distance = 1; distance < count; distance += 1) {
        if (windowRadius !== undefined && distance > windowRadius) break
        const before = priority - distance
        const after = priority + distance
        if (
          before >= 1 &&
          inWindow(before, priority) &&
          !attempted.has(before)
        ) {
          return before
        }
        if (
          after <= count &&
          inWindow(after, priority) &&
          !attempted.has(after)
        ) {
          return after
        }
        if (before < 1 && after > count) break
      }
      return undefined
    }

    // Text-only pass for pages outside the raster window — a few KB each,
    // so the whole document stays searchable without holding every bitmap.
    async function indexSheetText(
      url: string,
      pageNumber: number,
    ): Promise<void> {
      if (cancelled || !loaded) return
      const failuresTextKey = pageNumber + TEXT_KEY_OFFSET
      textDone.add(pageNumber)
      try {
        const page = await loaded.doc.getPage(pageNumber)
        const text = await extractPdfPageText(page)
        if (cancelled) return
        const id = `pdf-${pageNumber}`
        setDoc((current) =>
          current && current.url === url && current.sheets
            ? {
                ...current,
                sheets: current.sheets.map((sheet) =>
                  sheet.id === id
                    ? { ...sheet, text, textExtracted: true }
                    : sheet,
                ),
              }
            : current,
        )
      } catch {
        if (cancelled) return
        const count = (failures.get(failuresTextKey) ?? 0) + 1
        failures.set(failuresTextKey, count)
        if (count < MAX_PAGE_FAILURES) {
          // Transient — let the index drain re-pick it after a beat.
          textDone.delete(pageNumber)
          await new Promise((resolve) => setTimeout(resolve, 300))
          return
        }
        // Permanently unreadable — mark settled so the search-index signal
        // clears; the page simply stays unsearchable.
        const id = `pdf-${pageNumber}`
        setDoc((current) =>
          current && current.url === url && current.sheets
            ? {
                ...current,
                sheets: current.sheets.map((sheet) =>
                  sheet.id === id ? { ...sheet, textExtracted: true } : sheet,
                ),
              }
            : current,
        )
      }
    }

    // One sequential worker per document. Without a window it ends when every
    // page is painted; with a window it keeps filling the text index in the
    // background, then parks — the priority effect above wakes it on the next
    // page turn.
    async function drain(url: string): Promise<void> {
      const count = loaded?.doc.numPages ?? 0
      while (!cancelled && loaded) {
        const priority = Math.min(Math.max(1, priorityRef.current), count)
        prune(url, priority)
        const next = pickNext(priority, count)
        if (next !== undefined) {
          await renderSheet(url, next)
          continue
        }
        // Rasters for the visible range are done — spend idle time on the
        // text index, nearest unread page to the reading position first.
        let textNext: number | undefined
        if (extractText) {
          if (!textDone.has(priority)) textNext = priority
          for (
            let distance = 1;
            textNext === undefined && distance < count;
            distance += 1
          ) {
            if (
              priority - distance >= 1 &&
              !textDone.has(priority - distance)
            ) {
              textNext = priority - distance
            } else if (
              priority + distance <= count &&
              !textDone.has(priority + distance)
            ) {
              textNext = priority + distance
            }
          }
        }
        if (textNext !== undefined) {
          await indexSheetText(url, textNext)
          continue
        }
        if (windowRadius === undefined) return
        await new Promise<void>((resolve) => {
          wakeRef.current = resolve
        })
        wakeRef.current = null
      }
    }

    async function open(url: string) {
      try {
        passwordCancelledRef.current = false
        const result = await loadPdfDocument(url, {
          // A stalled fetch or dead worker must not spin the loader forever.
          timeoutMs: 60_000,
          onTask: (task) => {
            taskRef.current = task
          },
          onPassword: (request) => {
            if (cancelled) return
            passwordSubmitRef.current = request.submit
            setPasswordRequest({ incorrect: request.incorrect })
          },
        })
        loaded = result
        taskRef.current = result.task
        passwordSubmitRef.current = null
        setPasswordRequest(null)
        if (cancelled) {
          await result.task.destroy()
          return
        }
        const count = result.doc.numPages
        if (maxPages !== undefined && count > maxPages) {
          loaded = null
          await result.task.destroy()
          if (!cancelled) {
            reportError.current({
              kind: 'pdf-render',
              message: maxPagesMessage ?? message.current,
            })
          }
          return
        }
        // A 960px sheet at 2x is already roughly a 4MP bitmap. Capping DPR
        // avoids turning high-density phones into a large memory multiplier.
        pixelRatio =
          typeof window === 'undefined'
            ? 1
            : Math.min(2, Math.max(1, window.devicePixelRatio || 1))

        const firstPage = await result.doc.getPage(1)
        if (cancelled) return
        const baseRatio = pdfPageAspectRatio(firstPage)
        uniformHeight = Math.round(rasterWidth * baseRatio)

        setDoc({
          url,
          proxy: result.doc,
          ratio: baseRatio,
          sheets: Array.from({ length: count }, (_, index) => ({
            id: `pdf-${index + 1}`,
            src: '',
            width: rasterWidth,
            height: uniformHeight,
            text: '',
            textExtracted: false,
          })),
        })

        await drain(url)
      } catch {
        if (!cancelled) {
          reportError.current({
            kind: 'pdf-render',
            message: passwordCancelledRef.current
              ? 'This PDF is password-protected. Retry to enter its password.'
              : message.current,
          })
        }
      }
    }

    void open(pdfUrl)
    return () => {
      cancelled = true
      passwordSubmitRef.current = null
      setPasswordRequest(null)
      // Unpark the drain so it sees `cancelled` and exits.
      wakeRef.current?.()
      wakeRef.current = null
      // Destroy whichever task handle we hold — a password-pending document
      // never reached `loaded` but still owns a worker.
      void (taskRef.current ?? loaded?.task)?.destroy()
      taskRef.current = null
      for (const src of rendered.values()) releaseRasterUrl(src)
      rendered.clear()
    }
  }, [
    enabled,
    pdfUrl,
    rasterWidth,
    sizing,
    extractText,
    windowRadius,
    maxPages,
    maxPagesMessage,
  ])

  const active = enabled && pdfUrl && doc?.url === pdfUrl ? doc : null
  const activeSheets = active?.sheets ?? null
  const prepared = activeSheets?.filter((sheet) => sheet.src).length ?? 0
  // With a window, "preparing" means the visible range still has gaps — far
  // pages staying blank is the intended steady state, not ongoing work.
  const pendingInWindow =
    activeSheets?.some(
      (sheet, index) =>
        !sheet.src &&
        !sheet.failed &&
        (windowRadius === undefined ||
          Math.abs(index + 1 - (pageIndex + 1)) <= windowRadius),
    ) ?? false
  return {
    sheets: activeSheets,
    doc: active?.proxy ?? null,
    ratio: active?.ratio ?? null,
    prepared,
    preparing: enabled && activeSheets !== null && pendingInWindow,
    textPending:
      extractText &&
      enabled &&
      activeSheets !== null &&
      activeSheets.some((sheet) => !sheet.textExtracted),
    passwordRequest: enabled && pdfUrl ? passwordRequest : null,
    submitPassword,
    cancelPassword,
  }
}

